# Lưu danh mục thuốc ra file JSON
with open(os.path.join(RAW_DIR, "drugs_vietnam.json"), "w", encoding="utf-8") as f:
    json_drugs = []
    for brand_name, mfg, form, cat, ingredients in DRUGS:
        json_drugs.append({
            "brand_name": brand_name,
            "manufacturer": mfg,
            "dosage_form": form,
            "category": cat,
            "ingredients": [
                {
                    "inn_name": ing[0],
                    "strength": ing[1],
                    "atc_code": ing[2],
                    "drug_class": ing[3]
                } for ing in ingredients
            ]
        })
    json.dump(json_drugs, f, ensure_ascii=False, indent=2)

print(f"✅ Đã tạo file {os.path.join(RAW_DIR, 'drugs_vietnam.json')} thành công!")
